import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const C=JSON.parse('{"title":"对 Hilbert–Pólya 猜想的批判","description":"","frontmatter":{},"headers":[],"relativePath":"D026_HilbertPolya批判.md","filePath":"D026_HilbertPolya批判.md"}'),n={name:"D026_HilbertPolya批判.md"};function o(i,t,s,d,g,h){return a(),l("div",null,[...t[0]||(t[0]=[r('<div><h1 id="对-hilbert–polya-猜想的批判" tabindex="-1">对 Hilbert–Pólya 猜想的批判 <a class="header-anchor" href="#对-hilbert–polya-猜想的批判" aria-label="Permalink to &quot;对 Hilbert–Pólya 猜想的批判&quot;">​</a></h1><p><strong>——耦合常数量子力学（CQM）的方法论批判</strong></p><p><strong>作者</strong>：ruster</p><p><strong>框架</strong>：耦合常数量子力学（CQM）— 物理系统，主要费米—强子尺度</p><hr><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>对 Hilbert–Pólya 猜想百年历史进行根本性的方法论批判。标准数论路径将黎曼零点视为抽象复平面上的预先存在实体，试图通过心智构造一个厄米算符来“匹配”这些零点。论证：这一路径的百年失败不是技术挫折，而是结构性判决——纯数学框架内几乎不存在独立决定该算符谱的“额外信息”，已有构造都不可避免地陷入拟合循环。</p><p>在耦合常数量子力学（CQM）框架下，对 Hilbert–Pólya 猜想的<strong>扬弃</strong>（Aufheben）：保留其“厄米算符—离散实谱”的合理内核，否定其柏拉图主义的本体论预设，超越至“物理过程必然铸造算符”的唯物主义路径。CQM 从“物质先在”公理出发，将黎曼零点重新定位为质子禁闭内部前核子自组织过程的<strong>涌现几何签名</strong>，而非等待被匹配的抽象数学对象。退相干机制本身就是谱的铸造过程；证明退相干（紧化条件的可解性）等于证明 GL(5) 固定层级的零点猜想（实谱条件为广义黎曼猜想；黎曼猜想是其在 GL(1) 电磁因子层的特例）——两者是同一因果过程的几何表述与谱表述。</p><p>建立“自然性”的三个严格标准（因果解释性、逻辑独立性、物理统一性），论证 CQM 是在这三个标准上提供实质性物理机制的框架。CQM 的严格性缺口：黎曼算符 $\\hat{H} = \\hat{D}^2 + 1/4$ 目前仍是框架输入的脚手架，其从因果结构第一性原理的严格涌现尚未完成。</p><p><strong>关键词</strong>：Hilbert–Pólya 猜想；黎曼猜想；耦合常数量子力学；扬弃；历史唯物主义；因果集；退相干；非交换几何；Berry–Keating 对应</p><blockquote><p><strong>发生学分层定位</strong>：Hilbert–Pólya 猜想与黎曼猜想特指 <strong>GL(5) 固定层级</strong>——GL(5) 固定层级的实谱条件是广义黎曼猜想，黎曼猜想是其在 GL(1) 电磁因子层的特例。质数分布的基态同步是 SU(5)，SU(5) 来自 GL(5) 自守形式的紧化，而 GL(5) 自守形式依赖 Regge 底空间几何条件（非唯一）；<strong>物质自组织选中 GL(5)（SU(5) 是含标准模型的最小单群，rank 4）正是物质自组织的体现</strong>，$n > 5$ 层级不排除，但 GL(5) 主导物理谱。同步算符体系按谱论严格三分：<strong>紧化投影</strong>（GL(n) 自守空间 → 物理紧群表示空间，正交投影谱 ⊆ {0,1}）不可能携带零点谱，<strong>不是</strong>、也<strong>不可能</strong>成为波利亚算符；真正承担黎曼零点谱的对象是 GL(1) 电磁因子层的<strong>谱算符</strong> $\\hat{H} = \\hat{D}^2 + 1/4$，它在谱论<strong>类型上就是波利亚算符</strong>（谱等于零点虚部即波利亚判据）。<strong>符号说明</strong>：此处的 $\\hat{H} = \\hat{D}^2 + 1/4$ 是承担耦合谱 $\\mathfrak{c}_n = 1/4 + \\gamma_n^2$（本征值）的厄米谱算符，<strong>不是</strong>谱 $\\subseteq \\{0,1\\}$ 的紧化投影（同步算符 $\\hat{\\mathcal{S}}$）——若取紧化投影算符则 $\\hat{\\mathcal{S}}^2=\\hat{\\mathcal{S}}$，其平方加 $1/4$ 仍不能携带零点谱。故“谱等于零点虚部”是 $\\gamma_n \\leftrightarrow \\mathfrak{c}_n = 1/4+\\gamma_n^2$（$\\mathbb{R}_{>0}$ 上的双射）意义下的简写；本征值实性 $\\mathfrak{c}_n \\in \\mathbb{R} \\Leftrightarrow \\gamma_n$ 沿临界线，即波利亚判据。故不能笼统断言“承担零点谱的算符不是波利亚算符”——正确的区分在<strong>算符来源</strong>而非<strong>算符分类</strong>：CQM 的独到之处是给这一个波利亚算符以物理来源（紧化条件/退相干），而非按已知零点拟合其定义域与势，从而回避经典构造的拟合循环。批判对象是 Hilbert–Pólya 构造路径的方法论，其结论在分层后仍成立且被推广：GL(5) 固定层级的零点猜想需物理过程（紧化条件的可解性）而非心智构造来铸造。完整分层流程图见 <code>01 核心理论/CQM_核心_因果网络同步理论.md</code> §9。</p></blockquote><hr><h2 id="_1-引言-百年困境与范式转换" tabindex="-1">1. 引言：百年困境与范式转换 <a class="header-anchor" href="#_1-引言-百年困境与范式转换" aria-label="Permalink to &quot;1. 引言：百年困境与范式转换&quot;">​</a></h2><h3 id="_1-1-hilbert–polya-猜想的百年沉默" tabindex="-1">1.1 Hilbert–Pólya 猜想的百年沉默 <a class="header-anchor" href="#_1-1-hilbert–polya-猜想的百年沉默" aria-label="Permalink to &quot;1.1 Hilbert–Pólya 猜想的百年沉默&quot;">​</a></h3><p>1910 年代，George Pólya（及后来的 David Hilbert）提出一个影响深远的思想：若存在一个厄米算符 $\\hat{H}$，其本征值恰好对应黎曼 $\\zeta$ 函数的非平凡零点 $s_n = 1/2 + i\\gamma_n$，则黎曼猜想——所有非平凡零点位于临界线 $\\Re(s) = 1/2$——将自动成立，因为厄米算符的本征值必为实数。</p><p>一个世纪以来，这一猜想催生了大量数学工作：Berry–Keating 的 $xp$ 算符、Connes 的非交换几何迹公式、Sierra 的有限区间边界条件模型等。然而，<strong>核心目标始终未达成</strong>：没有人构造出一个严格自伴、其谱精确等于黎曼零点的算符。</p><p>论证如下：这种百年沉默不是暂时的技术挫折，而是<strong>结构性判决</strong>。它宣告了一条认识论路径的终结——纯数学框架内，通过构造算符来“匹配”黎曼零点的路径，本质上是不可行的。</p><h3 id="_1-2-从-构造-到-唯物发现-的范式转换" tabindex="-1">1.2 从“构造”到“唯物发现”的范式转换 <a class="header-anchor" href="#_1-2-从-构造-到-唯物发现-的范式转换" aria-label="Permalink to &quot;1.2 从“构造”到“唯物发现”的范式转换&quot;">​</a></h3><p>CQM（耦合常数量子力学）提出根本性的范式转换：</p><blockquote><p><strong>黎曼零点不是抽象复平面上等待被匹配的预先存在实体，而是质子禁闭内部前核子自组织过程的涌现几何签名。</strong></p></blockquote><p>在这一框架下，Hilbert–Pólya 猜想不是被“证明”的数学命题，而是被<strong>扬弃</strong>的环节——其“厄米算符—实谱”的对应结构被保留并纳入更广阔的物理理论，但其柏拉图主义的本体论预设被否定，其静态构造的方法论被超越为动态发现。</p><hr><h2 id="_2-hilbert–polya-猜想的历史与结构性失败" tabindex="-1">2. Hilbert–Pólya 猜想的历史与结构性失败 <a class="header-anchor" href="#_2-hilbert–polya-猜想的历史与结构性失败" aria-label="Permalink to &quot;2. Hilbert–Pólya 猜想的历史与结构性失败&quot;">​</a></h2><h3 id="_2-1-原始猜想与-berry–keating-对应" tabindex="-1">2.1 原始猜想与 Berry–Keating 对应 <a class="header-anchor" href="#_2-1-原始猜想与-berry–keating-对应" aria-label="Permalink to &quot;2.1 原始猜想与 Berry–Keating 对应&quot;">​</a></h3><p>Hilbert–Pólya 的核心直觉是：若 $\\hat{H}\\psi_n = \\gamma_n\\psi_n$ 且 $\\hat{H}^\\dagger = \\hat{H}$，则 $\\gamma_n \\in \\mathbb{R}$，即 $\\Re(s_n) = 1/2$。</p><p>1999 年，Berry 与 Keating 提出 $\\hat{H}_{BK} = \\frac{1}{2}(x\\hat{p} + \\hat{p}x)$（即 $xp$ 算符的对称化形式），指出其经典对应 $H = xp$ 的轨道周期与黎曼零点密度存在形式对应。然而，$\\hat{H}_{BK}$ 在半直线 $L^2(\\mathbb{R}_>, dx)$ 上<strong>形式对称但谱纯连续</strong>（本质自伴，亏指数 $(0,0)$），无离散本征值。</p><p>后续尝试（Connes 的 Adele 迹公式、Sierra 的有限区间模型、Bender 的 PT 对称推广等）均困于同一根本难题：<strong>算符的形式、定义域、边界条件无法从第一性原理独立确定，必须根据已知零点的位置进行后验调节</strong>。</p><h3 id="_2-2-三选一的死胡同" tabindex="-1">2.2 三选一的死胡同 <a class="header-anchor" href="#_2-2-三选一的死胡同" aria-label="Permalink to &quot;2.2 三选一的死胡同&quot;">​</a></h3><p>纯数学构造面临结构性三难困境：</p><table tabindex="0"><thead><tr><th style="text-align:left;">选择</th><th style="text-align:left;">数学结果</th><th style="text-align:left;">物理/数论后果</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>固定有限区间</strong></td><td style="text-align:left;">离散谱，但由边界条件人为锁定</td><td style="text-align:left;">谱密度无法自然匹配零点渐近分布</td></tr><tr><td style="text-align:left;"><strong>全实轴/半直线</strong></td><td style="text-align:left;">连续谱（谱纯连续）</td><td style="text-align:left;">无离散本征值，Hilbert–Pólya 空转</td></tr><tr><td style="text-align:left;"><strong>引入势场 $V(x)$</strong></td><td style="text-align:left;">可能获得离散谱</td><td style="text-align:left;">势场形式必须根据零点反推，陷入循环论证</td></tr></tbody></table><p><strong>关键洞察</strong>：纯数学框架内，决定谱的“额外信息”（边界条件、势场、截断尺度）无法从数学公理内部涌现，必须<strong>外部输入</strong>。而这个外部输入的唯一来源，就是<strong>已知零点的位置</strong>——这正是循环论证。</p><h3 id="_2-3-循环论证的陷阱" tabindex="-1">2.3 循环论证的陷阱 <a class="header-anchor" href="#_2-3-循环论证的陷阱" aria-label="Permalink to &quot;2.3 循环论证的陷阱&quot;">​</a></h3><p>所有现有构造共享同一认识论缺陷：</p><p>$$\\text{已知零点} \\xrightarrow{\\text{反推}} \\text{边界条件/势场/截断} \\xrightarrow{\\text{正向计算}} \\text{谱} \\approx \\text{已知零点}$$</p><p>输入依赖输出，输出验证输入。这不是推导，这是<strong>拟合</strong>。</p><hr><h2 id="_3-数学柏拉图主义的认识论批判" tabindex="-1">3. 数学柏拉图主义的认识论批判 <a class="header-anchor" href="#_3-数学柏拉图主义的认识论批判" aria-label="Permalink to &quot;3. 数学柏拉图主义的认识论批判&quot;">​</a></h2><h3 id="_3-1-数学柏拉图主义-vs-唯物主义" tabindex="-1">3.1 数学柏拉图主义 vs 唯物主义 <a class="header-anchor" href="#_3-1-数学柏拉图主义-vs-唯物主义" aria-label="Permalink to &quot;3.1 数学柏拉图主义 vs 唯物主义&quot;">​</a></h3><p>Hilbert–Pólya 传统的认识论本质是<strong>数学柏拉图主义</strong>：</p><ul><li><strong>真理的源头在独立于物质的数学世界</strong>：黎曼零点的“正确性”是数学家对数学世界的发现，自然是服从于数学的。</li><li><strong>物理对应是附会</strong>：若碰巧与某个物理系统相似，那是美学上的惊喜，不是本体论的必然。</li></ul><p>CQM 的认识论本质是<strong>唯物主义</strong>：</p><ul><li><strong>真理的源头在物质关系</strong>：黎曼零点的位置由物理定律必然决定，数学是自然的翻译。</li><li><strong>数学对应是涌现</strong>：算符的谱是物质再生产过程的肉身，不是数学世界的投影。</li><li><strong>数学是验证工具</strong>：数学的角色是验证物质世界本身的逻辑（物理构造是否确实给出零点谱），而非数学自为的场域中从公理自主证明。物理提供构造和推导锚点，数学进行检验——构造与验证分离（见 <code>04 前沿研究/CQM_前沿研究_黎曼猜想证明思路.md</code> §4.3）。</li></ul><h3 id="_3-2-拟合与推导" tabindex="-1">3.2 拟合与推导 <a class="header-anchor" href="#_3-2-拟合与推导" aria-label="Permalink to &quot;3.2 拟合与推导&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">拟合（Fitting）</th><th style="text-align:left;">推导（Derivation）</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>前提</strong></td><td style="text-align:left;">已知答案</td><td style="text-align:left;">不知答案</td></tr><tr><td style="text-align:left;"><strong>逻辑</strong></td><td style="text-align:left;">为得到 $X$，设定条件为 $X$</td><td style="text-align:left;">从原理出发，定律必然推出 $X$</td></tr><tr><td style="text-align:left;"><strong>追问“为什么”</strong></td><td style="text-align:left;">无法回答</td><td style="text-align:left;">可以回答</td></tr><tr><td style="text-align:left;"><strong>产物</strong></td><td style="text-align:left;">被捏造的算符</td><td style="text-align:left;">被发现的物理实在</td></tr></tbody></table><p>所有 Hilbert–Pólya 尝试都是拟合。CQM 的目标是推导。</p><hr><h2 id="_4-扬弃的哲学内涵" tabindex="-1">4. 扬弃的哲学内涵 <a class="header-anchor" href="#_4-扬弃的哲学内涵" aria-label="Permalink to &quot;4. 扬弃的哲学内涵&quot;">​</a></h2><h3 id="_4-1-正题-hilbert–polya-的合理内核" tabindex="-1">4.1 正题：Hilbert–Pólya 的合理内核 <a class="header-anchor" href="#_4-1-正题-hilbert–polya-的合理内核" aria-label="Permalink to &quot;4.1 正题：Hilbert–Pólya 的合理内核&quot;">​</a></h3><p>保留：</p><ul><li>厄米算符与离散实谱的对应思想</li><li>谱分析作为研究零点分布的工具</li><li>量子力学形式主义在数论问题中的启发价值</li></ul><h3 id="_4-2-反题-数学柏拉图主义的局限" tabindex="-1">4.2 反题：数学柏拉图主义的局限 <a class="header-anchor" href="#_4-2-反题-数学柏拉图主义的局限" aria-label="Permalink to &quot;4.2 反题：数学柏拉图主义的局限&quot;">​</a></h3><p>否定：</p><ul><li>零点作为抽象预先存在实体的柏拉图主义预设</li><li>数学在物理之外的独立本体论地位</li></ul><h3 id="_4-3-合题-cqm-的唯物主义超越" tabindex="-1">4.3 合题：CQM 的唯物主义超越 <a class="header-anchor" href="#_4-3-合题-cqm-的唯物主义超越" aria-label="Permalink to &quot;4.3 合题：CQM 的唯物主义超越&quot;">​</a></h3><p>超越：</p><ul><li>算符和零点都是退相干过程的<strong>涌现产物</strong></li><li>数学是物质展开自身的形式，不是数学世界的投影</li></ul><p><strong>扬弃的完成条件</strong>：当且仅当从因果结构第一性原理严格推导出 $\\hat{D} = -i(\\partial_u - 1/2)$ 是退相干的唯一可能输出时，Hilbert–Pólya 猜想才被真正扬弃——不是作为被否定的错误，而是作为被超越的环节。</p><hr><h2 id="_5-严格性缺口审计" tabindex="-1">5. 严格性缺口审计 <a class="header-anchor" href="#_5-严格性缺口审计" aria-label="Permalink to &quot;5. 严格性缺口审计&quot;">​</a></h2><h3 id="_5-1-关键缺口" tabindex="-1">5.1 关键缺口 <a class="header-anchor" href="#_5-1-关键缺口" aria-label="Permalink to &quot;5.1 关键缺口&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">缺口</th><th style="text-align:left;">内容</th><th style="text-align:left;">后果</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>C</strong></td><td style="text-align:left;">退相干稳态 = 正四单纯形</td><td style="text-align:left;">七大关联全部悬置（<code>01 核心理论/CQM_核心_集成理论.md</code> §7.1「一证七联」的七项关联）</td></tr><tr><td style="text-align:left;"><strong>G2</strong></td><td style="text-align:left;">耦合空间 $\\to$ 双曲 Laplacian 的必要性</td><td style="text-align:left;">算符形式仍是脚手架</td></tr><tr><td style="text-align:left;"><strong>G3</strong></td><td style="text-align:left;">$\\hat{D} = -i(\\partial_u - 1/2)$ 的唯一性</td><td style="text-align:left;">未证明退相干必然输出此算符</td></tr><tr><td style="text-align:left;"><strong>G4</strong></td><td style="text-align:left;">$\\hat{D} \\to \\hat{H} = \\hat{D}^2 + 1/4$ 的涌现</td><td style="text-align:left;">未从因果结构第一性原理推导</td></tr><tr><td style="text-align:left;"><strong>G5</strong></td><td style="text-align:left;">退相干 $\\to$ 边界条件 $\\vartheta_n$ 锁定</td><td style="text-align:left;">未写出退相干动力学方程</td></tr></tbody></table><p><strong>核心判断</strong>：黎曼算符 $\\hat{H} = \\hat{D}^2 + 1/4$ 目前仍是<strong>框架输入的脚手架</strong>（借自 Berry–Keating + 双曲几何），不是从因果结构第一性原理涌现的物理输出。在缺口 G2–G5 闭合之前，CQM 对 Hilbert–Pólya 的扬弃是<strong>哲学定性</strong>，而非<strong>数学定理</strong>。</p><h3 id="_5-2-物理真实性的判决标准——构造和推导锚点" tabindex="-1">5.2 物理真实性的判决标准——构造和推导锚点 <a class="header-anchor" href="#_5-2-物理真实性的判决标准——构造和推导锚点" aria-label="Permalink to &quot;5.2 物理真实性的判决标准——构造和推导锚点&quot;">​</a></h3><p>物理真实性的用处是<strong>提供构造和推导锚点</strong>：确保交叉证明中的存在性是物理真实而非数学构造——把“存在”从拟合提升为唯一物理机制。</p><p>CQM 不能仅凭数值巧合（$G_N$ 的 −3 ppm、$\\alpha^{-1}$ 的接近；均为构造后验数字校验，待独立复现）声称物理真实性。必须证明：</p><blockquote><p><strong>如果退相干输出不是 $\\hat{D} = -i(\\partial_u - 1/2)$，则 $G_N$、$\\alpha^{-1}$、质量谱必然偏离实验值若干数量级。</strong></p></blockquote><p>只有这一“反事实条件”被确立，算符的物理真实性才被判决。物理真实性提供构造和推导锚点（非拟合），数学验证管“定理成立”（谱确实是零点）——构造与验证分离（见 <code>04 前沿研究/CQM_前沿研究_黎曼猜想证明思路.md</code> §4.3）。</p><hr><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>Hilbert–Pólya 猜想的百年失败，是数学柏拉图主义构造路径的结构性判决。纯数学框架内，算符几乎无法从第一性原理独立涌现，已有构造都不可避免地依赖已知零点的后验调节，陷入循环论证。</p><p>CQM 提出对这一猜想的扬弃：保留其“厄米算符—实谱”的合理内核，否定其柏拉图主义本体论，超越至“物理过程必然铸造算符”的唯物主义路径。在这一框架中，黎曼零点不是抽象复平面上的等待者，而是质子禁闭内部前核子自组织过程的涌现几何签名。</p><p><strong>证明 GL(5) 固定层级的零点猜想（实谱条件为广义黎曼猜想；黎曼猜想是其在 GL(1) 电磁因子层的特例）= 证明紧化条件可解 = 证明退相干机制 = 证明正四单纯形稳态 = 证明 FG 在禁闭边界涌现。</strong> 这五个命题是同一因果过程的五个侧面。</p><p>然而，CQM 的哲学基因虽已完美，其数学表型尚未完全展开。黎曼算符 $\\hat{H} = \\hat{D}^2 + 1/4$ 目前仍是脚手架，其从因果结构 $(X, \\prec)$ 严格涌现的推导链是终极缺口。</p><p><strong>历史唯物主义的判断</strong>：数学真理的揭示是历史实践的产物，不是个人天才的私产。CQM 不需要等待黎曼再世——它需要的是从物质先在公理出发，逐步搭建、验证、撤除脚手架，直到黎曼算符作为退相干的几何必然被严格导出。</p><p>那时，Hilbert 和 Pólya 的问题将被彻底扬弃。不是被回答，而是被超越——因为答案不再是“是否存在”，而是“必须存在，而且这就是原因”。</p><hr><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ol><li>Berry, M. V., &amp; Keating, J. P. (1999). The Riemann zeros and eigenvalue asymptotics. <em>SIAM Rev.</em>, 41, 236.</li><li>Connes, A. (1994). <em>Noncommutative Geometry</em>. Academic Press.</li><li>Connes, A. (1999). Trace formula in noncommutative geometry and the zeros of the Riemann zeta function. <em>arXiv:math/9811068</em>.</li><li>Sierra, G. (2008). A quantum mechanical model of the Riemann zeros. <em>New J. Phys.</em>, 10, 033016.</li><li>Bombelli, L., Lee, J., Meyer, D., &amp; Sorkin, R. D. (1987). Space-time as a causal set. <em>Phys. Rev. Lett.</em>, 59, 521.</li><li>Feingold, A. J., Kleinschmidt, A., &amp; Nicolai, H. (2009). Hyperbolic Weyl groups and the four normed division algebras. <em>J. Algebra</em>, 322, 1295–1339.</li><li>Endres, S., &amp; Steiner, F. (2010). The Berry–Keating operator on $L^2(\\mathbb{R}_>,dx)$ and on compact quantum graphs with general self-adjoint realizations. <em>J. Phys. A: Math. Theor.</em>, 43, 095204. (arXiv:0912.3183) —— $H_{\\rm BK}$ 在 $L^2(\\mathbb R_>,dx)$ 上谱纯连续、亏指数 $(0,0)$。</li><li>ruster. (2026). <em>CNT 完整研究</em>. Zenodo. DOI: 10.5281/zenodo.20804380.</li><li>Marx, K. (1867). <em>Das Kapital: Kritik der politischen Ökonomie</em>. Hamburg: Otto Meissner.</li><li>Hegel, G. W. F. (1807). <em>Phänomenologie des Geistes</em>.</li></ol></div>',1)])])}const M=e(n,[["render",o]]);export{C as __pageData,M as default};
